-- ============================================================
-- PRICING MODELS
-- ============================================================
INSERT INTO pricing_models (
    pricing_model_id, name, description, pricing_method, currency, is_active
) VALUES
    (1, 'FTL Standard', 'Flat rate per full-truckload route: base charge plus a per-kilometre distance component.', 'flat_rate', 'EUR', 1),
    (2, 'LTL Weight-based', 'Per-kilogram charge with a minimum charge floor, for less-than-truckload and cross-docking shipments.', 'weight_based', 'EUR', 1),
    (3, 'Groupage Pallet-based', 'Per-pallet charge for consolidated groupage shipments travelling with compatible loads.', 'pallets', 'EUR', 1),
    (4, 'Moving Distance-based', 'Distance-based charge for household, office relocation and domestic moving jobs, plus a weight-linked handling component.', 'distance', 'EUR', 1),
    (5, 'Express Premium', 'Premium flat-rate pricing for time-critical express transport, reflecting limited capacity and priority scheduling.', 'flat_rate', 'EUR', 1),
    (6, 'Special Cargo Case Assessment', 'Mixed weight- and distance-based pricing for oversized or high-value cargo requiring individual case-by-case assessment.', 'mixed', 'EUR', 1);

