INSERT INTO issues (
    issue_id, job_id, client_id, issue_type, severity, status, reported_date,
    description, responsible_employee_id, company_decision, resolution,
    resolved_date, cost, client_compensation, notes, created_at
) VALUES
    (1, 42, 12, 'delay', 'high', 'open', '2026-02-24', 'Delivery arrived after the agreed delivery window due to route/border delays.', 15, 'Domestic movement within Germany; the CMR Convention does not apply. Liability assessed under standard national contract/tort principles and NordRoute''s terms of carriage.', NULL, NULL, 66.78, 66.78, NULL, '2026-02-24 17:00:00'),
    (2, 21, 3, 'delay', 'high', 'closed', '2026-02-02', 'Delivery arrived after the agreed delivery window due to route/border delays.', 15, 'International carriage subject to the CMR Convention. Delay in delivery established under Art. 19; compensation under Art. 23(5) is capped at the carriage charge for this consignment.', 'Compensation of 622.93 EUR paid to client per liability assessment; case closed.', '2026-02-07', 622.93, 622.93, NULL, '2026-02-02 10:00:00'),
    (3, 6, 8, 'delay', 'high', 'closed', '2026-01-30', 'Departure delayed by vehicle availability, causing late delivery.', 16, 'International carriage subject to the CMR Convention. Delay in delivery established under Art. 19; compensation under Art. 23(5) is capped at the carriage charge for this consignment.', 'Compensation of 254.19 EUR paid to client per liability assessment; case closed.', '2026-02-27', 254.19, 254.19, NULL, '2026-01-30 14:00:00'),
    (4, 5, 15, 'damage', 'medium', 'closed', '2026-01-27', 'Cargo showed water damage to outer packaging upon unloading.', 26, 'International carriage subject to the CMR Convention. Carrier liability established under Art. 17 for the affected portion of the consignment (~1,574 kg of 6,900 kg total). Claimed value 8,656.39 EUR is within the Art. 23(3) cap of 8.33 SDR/kg (~9.75 EUR/kg, i.e. 15,339.28 EUR); compensated at the assessed claimed value.', 'Compensation of 8,656.39 EUR paid to client per liability assessment; case closed.', '2026-02-08', 9243.3, 8656.39, NULL, '2026-01-27 17:00:00'),
    (5, 57, 4, 'delay', 'high', 'closed', '2026-02-26', 'Departure delayed by vehicle availability, causing late delivery.', 14, 'International carriage subject to the CMR Convention. Claim notice given 25 days after delivery, outside the Art. 30 notice period (21 days for delay). No evidence of wilful misconduct or equivalent fault by NordRoute or its driver. Claim contested; the notice-period defect does not itself extinguish the underlying CMR liability, but shifts the burden of proof for damage/loss onto the claimant, who has not discharged it in this case.', 'Claim contested and rejected on the stated basis; no compensation paid; case closed.', '2026-03-04', 9.9, 0.0, NULL, '2026-02-26 15:00:00'),
    (6, 36, 1, 'documentation', 'medium', 'closed', '2026-01-27', 'Discrepancy between invoice value and consignment note declared value.', 25, 'Documentation discrepancy identified and corrected by the Customs & Documentation team. No cargo loss or damage involved, so CMR cargo-liability provisions (Art. 17/23) do not apply; handled as an administrative/process matter under NordRoute''s service terms.', 'Claim contested and rejected on the stated basis; no compensation paid; case closed.', '2026-02-11', 81.31, 0.0, NULL, '2026-01-27 17:00:00'),
    (7, 18, 3, 'delay', 'low', 'closed', '2026-02-13', 'Departure delayed by vehicle availability, causing late delivery.', 19, 'International carriage subject to the CMR Convention. Claim notice given 25 days after delivery, outside the Art. 30 notice period (21 days for delay). No evidence of wilful misconduct or equivalent fault by NordRoute or its driver. Claim contested; the notice-period defect does not itself extinguish the underlying CMR liability, but shifts the burden of proof for damage/loss onto the claimant, who has not discharged it in this case.', 'Claim contested and rejected on the stated basis; no compensation paid; case closed.', '2026-03-06', 109.87, 0.0, NULL, '2026-02-13 12:00:00'),
    (8, 25, 11, 'damage', 'medium', 'closed', '2026-02-18', 'Partial damage to goods noted during unloading at destination.', 26, 'Domestic movement within Germany; the CMR Convention does not apply. Liability assessed under standard national contract/tort principles and NordRoute''s terms of carriage.', 'Compensation of 25,314.44 EUR paid to client per liability assessment; case closed.', '2026-03-02', 26457.53, 25314.44, NULL, '2026-02-18 14:00:00'),
    (9, 1, 8, 'delay', 'medium', 'closed', '2026-01-12', 'Delivery arrived after the agreed delivery window due to route/border delays.', 16, 'Domestic movement within Germany; the CMR Convention does not apply. Liability assessed under standard national contract/tort principles and NordRoute''s terms of carriage.', 'Compensation of 186.55 EUR paid to client per liability assessment; case closed.', '2026-01-28', 186.55, 186.55, NULL, '2026-01-12 10:00:00');

